import{_ as s,o as t,c as i,a0 as a}from"./chunks/framework.l1I-fhud.js";const g=JSON.parse('{"title":"Security model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/security.md","filePath":"explanation/security.md"}'),o={name:"explanation/security.md"};function n(r,e,d,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h1><p>Tamias moves other people&#39;s code onto your machine, so the threat model is <strong>supply chain</strong>: a malicious or tampered package, a hijacked ref, a poisoned registry. This page explains the layers; <code>SECURITY.md</code> at the repo root is the reporting policy.</p><h2 id="integrity-digests-and-pins" tabindex="-1">Integrity: digests and pins <a class="header-anchor" href="#integrity-digests-and-pins" aria-label="Permalink to &quot;Integrity: digests and pins&quot;">​</a></h2><p>Every install records three things in the store entry: the <strong>source ref</strong>, the <strong>resolved sha</strong> (commit sha for git, payload sha256 for tarballs), and the <strong>payload digest</strong>. <code>tamias verify</code> recomputes the digest and fails on mismatch — tampering with the store is detected.</p><p>Prefer pinned refs:</p><ul><li><code>…#sha256:&lt;hex&gt;</code> on an http tarball — verified <em>before</em> unpack.</li><li>git refs resolve to a commit sha up front, so the recorded <code>resolved</code> is immutable even when the branch moves.</li><li><code>cf:</code> registry installs carry the registry index digest — pinned by name@version plus that digest.</li></ul><p>Two honest caveats:</p><ul><li><code>http://</code> refs <strong>without</strong> a <code>#sha256:</code> pin fetch cleartext and warn on stderr. Use <code>https://</code> or pin the digest.</li><li><code>cf:</code> registry installs are TLS-authenticated but <strong>not</strong> sha-pinned at transport — the registry records a payload <em>directory</em> digest, not the tarball sha256. For end-to-end integrity prefer <code>git:</code> or an http ref with <code>#sha256:</code>.</li></ul><p>Two more warnings worth knowing:</p><ul><li><strong><code>include:</code> transitive fetches.</strong> A manifest <code>include:</code> that names a remote ref pulls <em>another</em> package at install time — and tamias warns when that ref is unpinned (an http(s) ref without <code>#sha256:</code>, or a <code>git:</code> rev that isn&#39;t a full 40-hex sha). The warning is advisory: remote includes are legitimate, but each one is a second supply-chain hop that bypasses whatever pin you put on the top-level ref.</li><li><strong>Cleartext registry index.</strong> Fetching <code>index.json</code> over <code>http://</code> warns on every call — the index is unauthenticated and modifiable in transit, so the payload digests it records are only as trustworthy as that GET. Signatures mitigate this <em>only</em> when <code>signing.allowed_signers</code> is configured (see below).</li></ul><p>Tarball unpacking is bounded independently of <code>max_download</code> (which caps the compressed blob): every untar enforces a <strong>2 GiB unpacked-size cap</strong> and a <strong>100k entry cap</strong>, so a tiny <code>.tgz</code> can&#39;t expand into disk or inode exhaustion. Manifest <code>type:</code>/<code>kind</code> strings are charset-validated (<code>[a-z0-9][a-z0-9._-]*</code>) because the kind becomes <code>tamias-driver-&lt;kind&gt;</code> in binary lookups — it can&#39;t smuggle path or option characters.</p><h2 id="trust-tiers-provenance-computed-not-declared" tabindex="-1">Trust tiers: provenance, computed not declared <a class="header-anchor" href="#trust-tiers-provenance-computed-not-declared" aria-label="Permalink to &quot;Trust tiers: provenance, computed not declared&quot;">​</a></h2><p>Signing is optional package signing (<code>ssh-keygen -Y</code>, namespace <code>tamias-package</code>) — <code>publish --sign</code> attaches a signature, <code>tamias-sign</code> verifies it. On top of raw signature status, every install and verify computes a <strong>trust tier</strong> and records it on the store entry (<code>trust</code> + <code>signer</code> fields):</p><table tabindex="0"><thead><tr><th>tier</th><th>meaning</th></tr></thead><tbody><tr><td><code>official</code></td><td>signature verifies against <code>signing.official_signers</code> — the small, curated trust set</td></tr><tr><td><code>signed</code></td><td>signature verifies against <code>signing.allowed_signers</code>, but not the official set</td></tr><tr><td><code>pinned</code></td><td>no verifiable signature, but the source ref carries an integrity pin (<code>cf:</code>, <code>#sha256:</code>, a full git sha)</td></tr><tr><td><code>unpinned</code></td><td>no signature and no pin — a moving branch/tag, bare http(s), a local path</td></tr><tr><td><code>bad</code></td><td>a signature is present and verification <strong>failed</strong> — a failed signature is never shown as merely unsigned</td></tr></tbody></table><p>The tier is <em>computed</em> from the ref, the signature, and your signers files — a package can&#39;t declare its own badge. Highest wins: an official signature short-circuits before <code>allowed_signers</code> is even consulted, and a present-but-failed signature beats any pin.</p><p>Where it surfaces:</p><ul><li><code>tamias list</code> — a <code>trust</code> column.</li><li><code>tamias info</code> / <code>tamias verify</code> — <code>trust</code> + <code>signer</code>; <code>--json</code> carries the same fields, and <code>verify</code> re-derives the tier live (a recorded signer wins, but a rotated <code>allowed_signers</code> file is honored).</li><li><code>tamias search</code> / <code>registry get</code> / <code>tamias serve</code> <code>verify</code> — <code>trust</code>/<code>signer</code>/<code>publisher</code> fields.</li><li><code>tamias ui</code> — trust badges.</li><li><code>tamias doctor</code> — reports the resolved <code>official_signers</code> path.</li></ul><h3 id="bootstrapping-official-signers" tabindex="-1">Bootstrapping <code>official_signers</code> <a class="header-anchor" href="#bootstrapping-official-signers" aria-label="Permalink to &quot;Bootstrapping \`official_signers\`&quot;">​</a></h3><p><code>allowed_signers</code> and <code>official_signers</code> are <strong>two different files</strong>: the first says &quot;this key may sign packages I install&quot;; the second is the smaller set that earns the <code>official</code> badge — think &quot;keys we ship under&quot; versus &quot;keys we merely tolerate&quot;. Resolution order for each (env wins):</p><table tabindex="0"><thead><tr><th>file</th><th>config</th><th>env</th><th>default</th></tr></thead><tbody><tr><td>allowed</td><td><code>signing.allowed_signers</code></td><td><code>TAMIAS_ALLOWED_SIGNERS</code></td><td><code>~/.config/tamias/allowed_signers</code></td></tr><tr><td>official</td><td><code>signing.official_signers</code></td><td><code>TAMIAS_OFFICIAL_SIGNERS</code></td><td><code>~/.config/tamias/official_signers</code></td></tr></tbody></table><p>Both are <code>ssh-keygen -Y</code> <code>allowed_signers</code> files (authorized_keys format, principals + keys). To mint an official identity:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/tamias-official</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># sign a package with it (key path resolution: $TAMIAS_SIGNING_KEY →</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># signing.key_env → signing.key):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TAMIAS_SIGNING_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">~/.ssh/tamias-official</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./mypkg</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># authorize the *public* key for the package&#39;s signing principal —</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># \`@scope/name\` for a scoped package, the bare \`name\` for unscoped:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;mypkg namespaces=&quot;tamias-package&quot; ssh-ed25519 AAAA…&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/tamias/official_signers</span></span></code></pre></div><p>Signing principals are <strong>scoped</strong>: a package <code>@scope/name</code> is signed and verified under the principal <code>@scope/name</code>; an unscoped package falls back to the bare <code>name</code> (and legacy records keep working the same way). <code>signing.required</code> additionally makes unsigned installs a hard error — but only <code>cf:</code>/registry refs can carry signatures, so <code>required</code> is a registry-policy switch; <code>tamias doctor</code> warns when <code>required</code> is set without a resolvable <code>allowed_signers</code>.</p><h2 id="drivers-are-code-—-consent-is-explicit-remembered-per-payload" tabindex="-1">Drivers are code — consent is explicit, remembered per payload <a class="header-anchor" href="#drivers-are-code-—-consent-is-explicit-remembered-per-payload" aria-label="Permalink to &quot;Drivers are code — consent is explicit, remembered per payload&quot;">​</a></h2><p>A package&#39;s <code>type:</code> names a <strong>driver</strong> (<code>tamias-driver-&lt;type&gt;</code>), which tamias executes as a subprocess. Drivers on <code>PATH</code> or in <code>&lt;tamias-home&gt;/drivers/</code> are trusted host tooling.</p><p>A package that <strong>ships its own <code>drivers/</code> dir</strong> is different: those binaries are arbitrary code inside the payload. Installing one requires explicit consent:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-drivers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">re</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or once per environment:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TAMIAS_ALLOW_DRIVERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">re</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><code>TAMIAS_ALLOW_DRIVERS=1</code> is a <strong>global bypass</strong> — it covers every install, including ones you haven&#39;t inspected; <code>tamias doctor</code> warns when it&#39;s set. Prefer <code>--allow-drivers</code> per install, or better, check the package first with <code>--plan</code>.</p><p><strong><code>tamias install --plan</code></strong> is the pre-flight check: a dry run that prints the ref, package identity, cache hit/miss, payload digest, trust tier + signer, signature status, <code>include:</code> resolutions, bundled drivers with their consent state, the resolved kind driver, provider services (deploy-only), and any problems — <strong>without executing drivers, committing to the store, or mutating anything</strong>. <code>--plan --json</code> gives the same picture machine-readably. It runs <code>capabilities</code> probes on discovered drivers (trusted local binaries), so it&#39;s safe to point at a ref you don&#39;t trust yet.</p><p>Consent is also <strong>remembered per package</strong>: after a granted install, tamias records <code>{label → payload digest, drivers, timestamp}</code> in <code>~/.config/tamias/consented.json</code> (<code>$TAMIAS_CONSENT_FILE</code> / <code>$XDG_CONFIG_HOME/tamias/</code> override the path). Re-installing the <em>same bytes</em> skips re-consent; a changed payload produces a new digest and re-prompts — consent binds to exact content, not to the package name. The memory is shared across surfaces: the CLI flag/env, the <code>tamias serve</code> <code>&quot;allow_drivers&quot;: true</code> request field, and the TUI consent modal all write the same file.</p><p>Without consent the install <strong>fails before anything is registered or run</strong> — no partial store entry, no copied driver.</p><p><strong>Executable surfaces are a separate, ungated channel.</strong> A package&#39;s <code>bins[]</code> (<code>payload:</code> entries under <code>tools/bin/</code>) and legacy <code>bin/</code> files deploy real binaries onto your <code>PATH</code> at install time with <strong>no consent prompt</strong> — the <code>--allow-drivers</code> gate covers <code>drivers/</code> only. A <code>shim: cli</code> entry is safe by construction (a generated script that execs <code>tamias bin exec</code>), but treat any pack that declares payload bins like you would a driver: inspect before installing (<code>tamias install --plan</code> lists declared bins).</p><h2 id="missing-drivers-fail-closed" tabindex="-1">Missing drivers fail closed <a class="header-anchor" href="#missing-drivers-fail-closed" aria-label="Permalink to &quot;Missing drivers fail closed&quot;">​</a></h2><p>Installing a package whose <code>type</code> has <strong>no</strong> discoverable driver fails the install (for any type other than <code>files</code>) — tamias never silently &quot;installs&quot; content it can&#39;t place. <code>tamias doctor</code> lists the drivers it found so you can see what&#39;s resolvable.</p><h2 id="secrets-are-names-never-values" tabindex="-1">Secrets are names, never values <a class="header-anchor" href="#secrets-are-names-never-values" aria-label="Permalink to &quot;Secrets are names, never values&quot;">​</a></h2><ul><li>Registry tokens live in env vars — <code>TAMIAS_REGISTRY_TOKEN</code> for http registries, or the env var <em>named</em> by a config <code>token_env</code> field. <code>tamias.yaml</code> / <code>tamias.lock</code> hold refs, names, and digests only.</li><li><code>tamias registry serve</code> is an open dev server unless you set <code>TAMIAS_REGISTRY_SERVE_TOKEN</code> (then every request needs <code>Authorization: Bearer …</code>).</li></ul><h2 id="tamias-serve-trusts-its-stdin" tabindex="-1"><code>tamias serve</code> trusts its stdin <a class="header-anchor" href="#tamias-serve-trusts-its-stdin" aria-label="Permalink to &quot;\`tamias serve\` trusts its stdin&quot;">​</a></h2><p>The ndjson service treats <strong>everything on stdin as trusted</strong>: an <code>install</code> op can pass <code>&quot;allow_drivers&quot;: true</code> — equivalent to <code>--allow-drivers</code> — and there&#39;s no per-request authentication. Embed it only behind a harness that has already made the trust decision; never expose <code>tamias serve</code> to untrusted input.</p><h2 id="git-fetch-hardening" tabindex="-1">Git fetch hardening <a class="header-anchor" href="#git-fetch-hardening" aria-label="Permalink to &quot;Git fetch hardening&quot;">​</a></h2><ul><li>Clone URLs are allowlisted: <code>https</code>, <code>http</code>, <code>ssh</code>, <code>git</code>, <code>file</code>, and scp-style <code>git@host:…</code>. Other schemes are rejected.</li><li>Revs are validated — no leading <code>-</code>, whitespace, <code>..</code>, or <code>//</code>, so a ref can&#39;t smuggle git options. Relative revs (<code>HEAD~2</code>, <code>main^</code>) are allowed.</li><li><code>GIT_TERMINAL_PROMPT=0</code> — a fetch never blocks on a credential prompt; it fails instead.</li></ul><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>Vulnerabilities go to the maintainers via GitHub private advisories — see <code>SECURITY.md</code>. Don&#39;t open public issues for security reports.</p>`,42)])])}const u=s(o,[["render",n]]);export{g as __pageData,u as default};
